import{_ as o,o as t,c as s,a2 as d}from"./chunks/framework.BDCokyix.js";const h=JSON.parse('{"title":"justfile helper summary","description":"","frontmatter":{},"headers":[],"relativePath":"development/justfile.md","filePath":"development/justfile.md","lastUpdated":1780254295000}'),c={name:"development/justfile.md"};function a(r,e,i,n,l,p){return t(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="justfile-helper-summary" tabindex="-1">justfile helper summary <a class="header-anchor" href="#justfile-helper-summary" aria-label="Permalink to &quot;justfile helper summary&quot;">​</a></h1><p>This repository exposes a root <code>justfile</code> as a convenience layer across the monorepo. It is intentionally a thin delegator now, not a replacement for the owning toolchains inside <code>backend/</code> and <code>desktop/</code>.</p><p>Ownership split:</p><ul><li><code>backend/</code> owns Cargo builds, tests, and <code>cargo xtask</code></li><li><code>desktop/</code> owns pnpm installs, Tauri builds, docs package builds, and packaging</li><li>the root <code>justfile</code> provides stable, easy-to-remember entry points while those boundaries are being made clearer</li></ul><p>Note: CI-critical automation uses <code>cargo xtask</code> for Cargo workspace tasks (see <code>docs/src/development/xtask.md</code>). Release builds live in <code>.github/workflows/release-desktop.yml</code> (the Tauri <code>desktop/desktop-app</code> bundles via <code>tauri-action</code>, signed/notarized on macOS) and <code>.github/workflows/release-server.yml</code> (<code>somad</code> Docker image to GHCR). The <code>justfile</code> remains shorthand for local development and light CI aggregation.</p><h2 id="preferred-grouped-targets" tabindex="-1">Preferred grouped targets <a class="header-anchor" href="#preferred-grouped-targets" aria-label="Permalink to &quot;Preferred grouped targets&quot;">​</a></h2><ul><li><strong>Backend builds / runs</strong> – <code>just backend-build-servers</code>, <code>just backend-run-bot</code>, <code>just backend-run-relay</code>, <code>just backend-run-rendezvous</code>, <code>just backend-run-bff</code>, <code>just backend-run-all</code> (all server subcommands dispatch to the single <code>somad</code> binary). <code>just backend-build-workspace</code> builds every crate + binary in the Rust workspace.</li><li><strong>Backend tests / xtask</strong> – <code>just backend-test</code>, <code>just backend-test-workspace</code>, <code>just backend-test-relay-smoke</code>, <code>just backend-test-rendezvous-smoke</code>, <code>just backend-xtask-help</code>, <code>just backend-xtask-version-workspace</code></li><li><strong>Desktop workspace</strong> – <code>just desktop-install</code>, <code>just desktop-run-soma</code> (Tauri dev), <code>just desktop-build-soma</code> (Tauri bundle), <code>just desktop-test-soma</code>, <code>just desktop-test-all</code>, <code>just desktop-test-unit</code>, <code>just desktop-test-e2e</code></li><li><strong>Docs / shared publish helpers</strong> – <code>just docs-build</code></li><li><strong>Compose helpers</strong> – <code>just compose-up</code>, <code>just compose-logs</code>, <code>just compose-ps</code>, <code>just compose-down</code></li><li><strong>CI aggregations</strong> – <code>just ci-backend</code>, <code>just ci-desktop</code>, <code>just ci-verify</code></li><li><strong>Helpers</strong> – <code>just help</code> (prints the full recipe list)</li></ul><p>If you need to extend workflows, prefer keeping the real command in the owning workspace and then add a small delegating recipe at the repo root only if it improves discoverability.</p><p>The unprefixed transitional aliases (<code>run-daemon</code>, <code>test-backend</code>, <code>run-soma-desktop</code>, and the per-service <code>run-*d</code> daemon names) have been removed along with the per-service backend binaries they pointed at. Use the grouped names above so backend-vs-desktop ownership stays obvious.</p><h2 id="desktop-icons" tabindex="-1">Desktop icons <a class="header-anchor" href="#desktop-icons" aria-label="Permalink to &quot;Desktop icons&quot;">​</a></h2><p>The Tauri app&#39;s bundle icons live at <code>desktop/desktop-app/src-tauri/icons/</code> (<code>32x32.png</code>, <code>128x128.png</code>, <code>128x128@2x.png</code>, <code>icon.icns</code>, <code>icon.ico</code>, <code>icon.png</code>). Regenerate them from a single 1024×1024 source with Tauri&#39;s own tooling (<code>pnpm --filter @soma/desktop-app exec tauri icon /path/to/icon.png</code>), which writes the full icon set into <code>src-tauri/icons/</code>. (The Cargo icon crate lives at <code>desktop/desktop-icons</code>.)</p><h2 id="when-to-use-the-root-justfile" tabindex="-1">When to use the root <code>justfile</code> <a class="header-anchor" href="#when-to-use-the-root-justfile" aria-label="Permalink to &quot;When to use the root `justfile`&quot;">​</a></h2><p>Use the root <code>justfile</code> when you want:</p><ul><li>one command from the repo root for common local workflows</li><li>grouped backend vs desktop entry points that are easy to discover</li><li>light CI aggregation without hiding which workspace owns the underlying commands</li></ul><p>Skip the root <code>justfile</code> and work directly in <code>backend/</code> or <code>desktop/</code> when you are doing deeper workflow development for that area.</p><h2 id="shell-ergonomics" tabindex="-1">Shell ergonomics <a class="header-anchor" href="#shell-ergonomics" aria-label="Permalink to &quot;Shell ergonomics&quot;">​</a></h2><p><code>just</code> works across shells, but contributors on <code>zsh</code> benefit from <a href="https://github.com/JBarberU/zsh-justfile" target="_blank" rel="noreferrer">JBarberU/zsh-justfile</a>. Installing that plugin adds tab completion, descriptions, and the ability to list known recipes without memorizing names.</p>',17)])])}const k=o(c,[["render",a]]);export{h as __pageData,k as default};
